mapper.select:
WITH T0 AS ( SELECT DISTINCT PORDERP.POHNUM_0, PORDERP.POPLIN_0, PORDERP.PJT_0, PORDERP.ITMREF_0, PORDERP.CREDAT_0, PORDERP.CREUSR_0 FROM EXPLOIT.PORDERP AS PORDERP INNER JOIN EXPLOIT.PORDERQ AS PORDERQ ON PORDERP.POHNUM_0 = PORDERQ.POHNUM_0 AND PORDERP.POPLIN_0 = PORDERQ.POPLIN_0 WHERE 1=1
AND PORDERP.PRHFCY_0 IN ('ZHU','HKG','YSH')
AND PORDERP.PRHFCY_0 = #{Site}
AND PORDERQ.LINCLEFLG_0 = 1 --- line open flag, exclude manual closed po line AND PORDERP.NETPRI_0 > 0 --- exclude manually mark 0, it's an error line AND SUBSTRING(PORDERP.POHNUM_0, 2, 2) != 'CT' --- exclude delivery ), T1 AS ( SELECT DISTINCT PRECEIPTD.POHNUM_0, PRECEIPTD.POPLIN_0 FROM EXPLOIT.PRECEIPTD AS PRECEIPTD WHERE 1=1
AND PRECEIPTD.PRHFCY_0 IN ('ZHU','HKG','YSH')
AND PRECEIPTD.PRHFCY_0 = #{Site}
), T2 AS ( SELECT T0.POHNUM_0, T0.POPLIN_0, T0.PJT_0, T0.ITMREF_0, T0.CREDAT_0, T0.CREUSR_0 FROM T0 LEFT JOIN T1 ON T1.POHNUM_0 = T0.POHNUM_0 AND T1.POPLIN_0 = T0.POPLIN_0 WHERE T1.POHNUM_0 IS NULL AND T1.POPLIN_0 IS NULL ), T3 AS ( SELECT DISTINCT IIF(SORDERQ.YSOQ_PJTORI_0 = '', SORDERQ.YSOH_PJT_0, SORDERQ.YSOQ_PJTORI_0) AS ProjectNO, SORDERQ.SOHNUM_0 AS OrderNO, SORDERQ.ITMREF_0 AS PN, SORDERQ.QTY_0 AS Qty, SORDER.ORDDAT_0 AS OrderDate FROM EXPLOIT.SORDERQ AS SORDERQ INNER JOIN EXPLOIT.SORDER SORDER ON SORDERQ.SOHNUM_0 = SORDER.SOHNUM_0
AND SORDERQ.SALFCY_0 IN ('ZHU','HKG','YSH')
AND SORDERQ.SALFCY_0 = #{Site}
AND SORDERQ.SOQSTA_0 = 3 )
SELECT DISTINCT T2.POHNUM_0 AS PurchaseNO, T2.POPLIN_0 AS PurchaseLine, T2.ITMREF_0 AS PurchasePN, T2.CREDAT_0 AS PurchaseDate, T2.CREUSR_0 AS Purchaser, T3.ProjectNO, T3.OrderNO, T3.PN AS SalesPN, T3.Qty, T3.OrderDate FROM T2 INNER JOIN T3 ON T2.PJT_0 = T3.ProjectNO ORDER BY T3.OrderDate ASC

WITH T0 AS ( SELECT DISTINCT SORDERQ.YSOH_PJT_0 AS ProjectNO, SORDERQ.SOHNUM_0 AS OrderNO FROM EXPLOIT.SORDERQ SORDERQ ), T1 AS ( SELECT DISTINCT PORDERP.POHNUM_0 AS PurchaseNO, PORDERP.POPLIN_0 AS Line, PORDERP.PJT_0 AS ProjectNO, PORDERP.ITMREF_0 AS PN, PORDERP.ITMDES_0 AS Description, PORDER.CUR_0 AS Currency, PORDERP.NETPRI_0 AS NetPrice, PORDERQ.QTYPUU_0 AS QTY, PORDERQ.PUU_0 AS Unit, PORDER.BPSNUM_0 AS VendorCode, PORDER.BPRNAM_0 AS VendorName, IIF(PORDERQ.LINOCNDAT_0='1753-01-01', PORDERQ.EXTRCPDAT_0, PORDERQ.LINOCNDAT_0) AS AckDate, PORDERQ.EXTRCPDAT_0 AS ExpectDate, PORDER.ORDDAT_0 AS OrderDate, PORDER.CREUSR_0 AS CreateUser FROM EXPLOIT.PORDERP PORDERP INNER JOIN EXPLOIT.PORDERQ AS PORDERQ ON PORDERP.POHNUM_0=PORDERQ.POHNUM_0 AND PORDERP.POPLIN_0=PORDERQ.POPLIN_0 AND PORDERQ.LINCLEFLG_0 != 2 INNER JOIN EXPLOIT.PORDER AS PORDER ON PORDERP.POHNUM_0=PORDER.POHNUM_0 WHERE ( SUBSTRING(PORDERP.PJT_0,2,2) = 'CC' OR SUBSTRING(PORDERP.PJT_0,2,4) = 'DSRP' )
AND PORDERP.PRHFCY_0 IN ('ZHU','HKG','YSH')
AND PORDERP.PRHFCY_0 = #{Site}
)
SELECT T1.* FROM T1 LEFT JOIN T0 ON T1.ProjectNO = T0.ProjectNO WHERE T0.OrderNO IS null ORDER BY T1.OrderDate ASC

WITH T0 AS ( -- find open project SELECT DISTINCT SORDERQ.YSOH_PJT_0 AS ProjectNO, SORDERQ.YSOQ_PJTORI_0 AS ProjectOriNO FROM EXPLOIT.SORDERQ AS SORDERQ WHERE 1=1 AND SORDERQ.SOQSTA_0 != 3
AND SORDERQ.SALFCY_0 IN ('ZHU','HKG','YSH')
AND SORDERQ.SALFCY_0 = #{Site}
), T1 AS ( -- find NC project SELECT SERREQUEST.YORIPJT_0, SERREQUEST.CREDAT_0 FROM T0 INNER JOIN EXPLOIT.SERREQUEST SERREQUEST ON ( T0.ProjectNO = SERREQUEST.YORIPJT_0 OR T0.ProjectOriNO = SERREQUEST.YORIPJT_0 ) AND SERREQUEST.YORIPJT_0 != '' AND 1=1 ), T2 AS ( SELECT DISTINCT PORDERP.POHNUM_0 AS PurchaseNO, PORDERP.POPLIN_0 AS Line, PORDERP.PJT_0 AS ProjectNO, PORDERP.ITMREF_0 AS PN, PORDERP.ITMDES_0 AS Description, PORDER.CUR_0 AS Currency, PORDERP.NETPRI_0 AS NetPrice, PORDERQ.QTYPUU_0 AS QTY, PORDERQ.PUU_0 AS Unit, PORDER.BPSNUM_0 AS VendorCode, PORDER.BPRNAM_0 AS VendorName, T1.CREDAT_0 AS FirstNCDate, PORDER.ORDDAT_0 AS OrderDate, PORDER.CREUSR_0 AS CreateUser FROM T1 INNER JOIN EXPLOIT.PORDERP AS PORDERP ON T1.YORIPJT_0 = PORDERP.PJT_0 INNER JOIN EXPLOIT.PORDERQ AS PORDERQ ON PORDERP.POHNUM_0=PORDERQ.POHNUM_0 AND PORDERP.POPLIN_0=PORDERQ.POPLIN_0 INNER JOIN EXPLOIT.PORDER AS PORDER ON PORDERP.POHNUM_0 = PORDER.POHNUM_0 WHERE PORDERP.ITMREF_0 LIKE 'PNOG%' -- only PNOG AND GETDATE() >= DATEADD(DAY, #{Days}, T1.CREDAT_0) )
SELECT * FROM T2 ORDER BY T2.FirstNCDate ASC

WITH T0 AS ( -- find open project SELECT DISTINCT SORDERQ.YSOH_PJT_0 AS ProjectNO, SORDERQ.YSOQ_PJTORI_0 AS ProjectOriNO FROM EXPLOIT.SORDERQ AS SORDERQ WHERE 1=1 AND SORDERQ.SOQSTA_0 != 3
AND SORDERQ.SALFCY_0 IN ('ZHU','HKG','YSH')
AND SORDERQ.SALFCY_0 = #{Site}
), T1 AS ( -- find open porject receive SELECT PRECEIPTD.PJT_0, PRECEIPTD.CREDAT_0, PRECEIPTD.CREUSR_0 FROM T0 INNER JOIN EXPLOIT.PRECEIPTD PRECEIPTD ON ( T0.ProjectNO = PRECEIPTD.PJT_0 OR T0.ProjectOriNO = PRECEIPTD.PJT_0 ) AND PRECEIPTD.PJT_0 != '' AND PRECEIPTD.ITMREF_0 LIKE 'PNOG%' ), T2 AS ( SELECT DISTINCT PORDERP.POHNUM_0 AS PurchaseNO, PORDERP.POPLIN_0 AS Line, PORDERP.PJT_0 AS ProjectNO, PORDERP.ITMREF_0 AS PN, PORDERP.ITMDES_0 AS Description, PORDER.CUR_0 AS Currency, PORDERP.NETPRI_0 AS NetPrice, PORDERQ.QTYPUU_0 AS QTY, PORDERQ.PUU_0 AS Unit, PORDER.BPSNUM_0 AS VendorCode, PORDER.BPRNAM_0 AS VendorName, PORDER.ORDDAT_0 AS OrderDate, PORDER.CREUSR_0 AS CreateUser, T1.CREDAT_0 AS ReceiptDate, T1.CREUSR_0 AS Receiptor FROM T1 INNER JOIN EXPLOIT.PORDERP AS PORDERP ON T1.PJT_0 = PORDERP.PJT_0 INNER JOIN EXPLOIT.PORDERQ AS PORDERQ ON PORDERP.POHNUM_0=PORDERQ.POHNUM_0 AND PORDERP.POPLIN_0=PORDERQ.POPLIN_0 AND PORDERQ.PRHFCY_0 = #{Site} AND PORDERP.PRHFCY_0 = #{Site} INNER JOIN EXPLOIT.PORDER AS PORDER ON PORDERP.POHNUM_0 = PORDER.POHNUM_0 LEFT JOIN EXPLOIT.SERREQUEST SERREQUEST ON T1.PJT_0 = SERREQUEST.YORIPJT_0 WHERE PORDERP.ITMREF_0 LIKE 'PNOG%' AND SERREQUEST.YORIPJT_0 IS NULL AND GETDATE() >= DATEADD(DAY, #{Days}, T1.CREDAT_0) )
SELECT DISTINCT * FROM T2 ORDER BY T2.ReceiptDate ASC
